// Generates src/environments/environment.ts from environment variables or a
// local .env file. The generated file is git-ignored; only public values
// (project URL and anon/publishable key) are accepted here.
import { mkdirSync, writeFileSync } from 'node:fs';
import { loadEnv } from './load-env.mjs';

loadEnv();

const url = process.env.DIDIFLOW_SUPABASE_URL?.trim();
const anonKey = process.env.DIDIFLOW_SUPABASE_ANON_KEY?.trim();

function fail(message) {
  console.error(`write-env: ${message}\nSee .env.example and docs/security.md.`);
  process.exit(1);
}

if (!url || !anonKey) {
  fail('DIDIFLOW_SUPABASE_URL and DIDIFLOW_SUPABASE_ANON_KEY are required.');
}

let parsed;
try {
  parsed = new URL(url);
} catch {
  fail(`DIDIFLOW_SUPABASE_URL is not a valid URL: ${url}`);
}

const isLocal = ['127.0.0.1', 'localhost'].includes(parsed.hostname);
// Android debug builds (scripts/build-android.mjs) may reach a local Supabase
// on the LAN over http; never allowed for regular builds.
const isPrivateLan =
  process.env.DIDIFLOW_ALLOW_LAN_HTTP === '1' &&
  /^(10.|192.168.|172.(1[6-9]|2d|3[01]).)/.test(parsed.hostname);
if (parsed.protocol !== 'https:' && !((isLocal || isPrivateLan) && parsed.protocol === 'http:')) {
  fail('DIDIFLOW_SUPABASE_URL must use https (http is allowed only for a local Supabase).');
}

// Guard against the most damaging mistake: shipping a privileged key.
if (anonKey.startsWith('sb_secret_') || decodeJwtRole(anonKey) === 'service_role') {
  fail('DIDIFLOW_SUPABASE_ANON_KEY looks like a service_role/secret key. Never ship it.');
}

mkdirSync('src/environments', { recursive: true });
writeFileSync(
  'src/environments/environment.ts',
  `// Generated by scripts/write-env.mjs. Do not edit or commit.
import type { AppEnvironment } from '../app/core/config/app-environment';

export const environment: AppEnvironment = {
  supabaseUrl: ${JSON.stringify(parsed.origin)},
  supabaseAnonKey: ${JSON.stringify(anonKey)},
};
`,
);
console.log(`write-env: environment.ts generated for ${parsed.origin}`);

function decodeJwtRole(token) {
  const payload = token.split('.')[1];
  if (!payload) return undefined;
  try {
    return JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')).role;
  } catch {
    return undefined;
  }
}
